(()=>{'use strict';const root=document.getElementById('P23-lab');if(!root)return;const zh=document.documentElement.lang.startsWith('zh'),tr=(z,e)=>zh?z:e,$=x=>root.querySelector('#P23-'+x),colors=['#28658c','#c26835'];let state={model:'adjusted',offset:-10,perturbation:0,focus:18},result={};
const mean=a=>a.reduce((s,v)=>s+v,0)/a.length;function fit(rows,adjusted){const groups=adjusted?[rows.filter(r=>r.batch===0),rows.filter(r=>r.batch===1)]:[rows],centers=groups.map(g=>[mean(g.map(r=>r.x)),mean(g.map(r=>r.y))]);let numerator=0,denominator=0;groups.forEach((g,j)=>g.forEach(r=>{numerator+=(r.x-centers[j][0])*(r.y-centers[j][1]);denominator+=(r.x-centers[j][0])**2}));let slope=numerator/denominator,intercept=centers[0][1]-slope*centers[0][0],shift=adjusted?centers[1][1]-slope*centers[1][0]-intercept:0;const predict=r=>intercept+slope*r.x+shift*r.batch,residuals=rows.map(r=>r.y-predict(r));return{slope,intercept,shift,predict,residuals,sse:residuals.reduce((s,v)=>s+v*v,0)}}
const text=(x,y,s,a='start',size=14)=>`<text x="${x}" y="${y}" text-anchor="${a}" font-size="${size}" fill="#20313e">${s}</text>`;
function chart(el,w,h,xmin,xmax,ymin,ymax,xlabel,ylabel,title,categorical=false){el.setAttribute('viewBox',`0 0 ${w} ${h}`);const l=65,r=w-18,t=42,b=h-66,x=v=>l+(v-xmin)/(xmax-xmin)*(r-l),y=v=>b-(v-ymin)/(ymax-ymin)*(b-t);let s=text(l,22,title,'start',16);if(!categorical)for(let v=Math.ceil(xmin);v<=xmax;v++)s+=text(x(v),b+22,v,'middle');const intervals=categorical?6:4;for(let i=0;i<=intervals;i++){const v=ymin+(ymax-ymin)*i/intervals;s+=`<path d="M${l},${y(v)}H${r}" stroke="#e5ebef"/>`+text(l-8,y(v)+5,Number(v.toFixed(3)),'end')}s+=text((l+r)/2,h-12,xlabel,'middle')+`<text transform="translate(17 ${(t+b)/2}) rotate(-90)" text-anchor="middle" font-size="14">${ylabel}</text>`;return{x,y,l,r,t,b,s}}
function render(){const rows=[];for(let batch=0;batch<2;batch++)for(let k=1;k<=3;k++)for(const error of [-.4,0,.4]){let x=k+batch*3;rows.push({id:rows.length+1,batch,x,y:10+2*x+batch*state.offset+error})}rows[17].y+=state.perturbation;const adjusted=fit(rows,true),pooled=fit(rows,false),leave=fit(rows.slice(0,-1),true),model=state.model==='adjusted'?adjusted:pooled,picked=rows[state.focus-1];let a=chart($('data'),900,390,0,7,0,32,tr('浓度 / mmol·L⁻¹','Concentration / mmol·L⁻¹'),tr('响应 / kPa','Response / kPa'),tr('试样、批次与当前拟合','Specimens, batches, and the current fit')),s=a.s;
for(const row of rows){s+=`<circle cx="${a.x(row.x)}" cy="${a.y(row.y)}" r="4" fill="${colors[row.batch]}"/>`;if(row.id===state.focus)s+=`<circle cx="${a.x(row.x)}" cy="${a.y(row.y)}" r="8" fill="none" stroke="#20313e" stroke-width="2"/>`}
for(const batch of state.model==='adjusted'?[0,1]:[0]){const x1=state.model==='adjusted'?1+batch*3:1,x2=state.model==='adjusted'?3+batch*3:6;s+=`<path d="M${a.x(x1)},${a.y(model.predict({x:x1,batch}))}L${a.x(x2)},${a.y(model.predict({x:x2,batch}))}" stroke="${state.model==='adjusted'?colors[batch]:'#20313e'}" stroke-width="2.5"/>`}$('data').innerHTML=s;
const lim=Math.max(.5,Math.ceil(Math.max(...model.residuals.map(Math.abs))*2)/2),b=chart($('residual'),450,365,0,7,-lim,lim,tr('浓度 / mmol·L⁻¹','Concentration / mmol·L⁻¹'),tr('残差 / kPa','Residual / kPa'),tr('同一批点的残差','Residuals of the same observations'));s=b.s+`<path d="M${b.l},${b.y(0)}H${b.r}" stroke="#20313e"/>`;rows.forEach((row,i)=>{s+=`<circle cx="${b.x(row.x)}" cy="${b.y(model.residuals[i])}" r="4" fill="${colors[row.batch]}"/>`;if(row.id===state.focus)s+=`<circle cx="${b.x(row.x)}" cy="${b.y(model.residuals[i])}" r="8" fill="none" stroke="#20313e" stroke-width="2"/>`});$('residual').innerHTML=s;
const values=[pooled.slope,adjusted.slope,leave.slope],c=chart($('coefficients'),450,365,-.5,2.5,-2,4,'',tr('斜率 / kPa·L·mmol⁻¹','Slope / kPa·L·mmol⁻¹'),tr('三种条件下的浓度系数','Concentration coefficient in three fits'),true);s=c.s+`<path d="M${c.l},${c.y(0)}H${c.r}" stroke="#20313e"/>`;const labels=[tr('合并','Pooled'),tr('批次','Batch'),tr('去掉18号','Without 18')];values.forEach((v,i)=>{s+=`<circle cx="${c.x(i)}" cy="${c.y(v)}" r="6" fill="${i===0?'#20313e':i===1?colors[0]:'#b64a35'}"/>`+text(c.x(i),c.y(v)-12,v.toFixed(4),'middle')+text(c.x(i),c.b+25,labels[i],'middle',13)});$('coefficients').innerHTML=s;
result={...state,slope:model.slope,intercept:model.intercept,shift:model.shift,sse:model.sse,prediction:model.predict(picked),observation:picked.y,pooledSlope:pooled.slope,adjustedSlope:adjusted.slope,leave18outSlope:leave.slope};$('readout').textContent=tr(`B偏移 ${state.offset} kPa，18号增加 ${state.perturbation} kPa；当前斜率 ${model.slope.toFixed(5)} kPa·L/mmol，SSE ${model.sse.toFixed(4)} kPa²。${state.focus}号：浓度 ${picked.x} mmol/L，观测 ${picked.y.toFixed(3)} kPa，预测 ${result.prediction.toFixed(3)} kPa。`,`B shift ${state.offset} kPa; specimen 18 receives +${state.perturbation} kPa. Current slope ${model.slope.toFixed(5)} kPa·L/mmol, SSE ${model.sse.toFixed(4)} kPa². Specimen ${state.focus}: concentration ${picked.x} mmol/L, observed ${picked.y.toFixed(3)} kPa, predicted ${result.prediction.toFixed(3)} kPa.`);for(const key of ['model','offset','perturbation','focus'])$(key).value=state[key];return result}
function set(p={}){if(['adjusted','pooled'].includes(p.model))state.model=p.model;for(const[key,lo,hi]of[['offset',-12,0],['perturbation',0,8],['focus',1,18]])if(Number.isFinite(Number(p[key])))state[key]=Math.round(Math.max(lo,Math.min(hi,Number(p[key]))));return render()}function reset(){state={model:'adjusted',offset:-10,perturbation:0,focus:18};return render()}for(const key of ['model','offset','perturbation','focus'])$(key).addEventListener('input',()=>set({[key]:$(key).value}));$('reset').addEventListener('click',reset);let ro;if(typeof ResizeObserver!=='undefined'){ro=new ResizeObserver(render);ro.observe(root)}window.CourseLab={set,state:()=>({...result}),reset,destroy:()=>ro?.disconnect()};render()})();
